async def act(page):
    import re
    import asyncio

    # No knowledge_base helper functions are available for this task, so use Playwright APIs only.

    # Use the document root from the accessibility tree as an unambiguous starting point
    root = page.get_by_role("document", name="Tori Tank / Manage Products / Catalog / Magento Admin")

    # 1) Reveal the Prices panel in the Product Information navigation
    await root.get_by_role("link", name="Prices").click()
    # allow the Prices panel to render
    await asyncio.sleep(1)

    # 2) Locate the Price input using accessible-role selectors only (search inside the main table)
    price_locator = None
    table = root.get_by_role("table")

    # Try common roles with accessible name "Price"
    for role in ("spinbutton", "textbox"):
        try:
            candidate = table.get_by_role(role, name="Price")
            await candidate.wait_for(state="visible", timeout=2000)
            price_locator = candidate
            break
        except Exception:
            pass

    # 3) Fallback: scan spinbutton/textbox elements under the table for a numeric-looking value
    if not price_locator:
        for role in ("spinbutton", "textbox"):
            try:
                collection = table.get_by_role(role)
                count = await collection.count()
            except Exception:
                continue

            for i in range(count):
                candidate = collection.nth(i)
                try:
                    val = await candidate.input_value()
                except Exception:
                    try:
                        val = (await candidate.text_content()) or ""
                    except Exception:
                        val = ""

                if not val or not re.search(r"\d", val):
                    continue

                s = val.replace('\u00a0', '').strip()
                m = re.search(r"([0-9\.,]+)", s)
                cleaned = m.group(1) if m else re.sub(r"[^0-9\.,]", "", s)

                if "," in cleaned and "." in cleaned:
                    cleaned = cleaned.replace(",", "")
                elif "," in cleaned and "." not in cleaned:
                    cleaned = cleaned.replace(",", ".")

                if not cleaned:
                    continue

                try:
                    float(cleaned)
                    price_locator = candidate
                    break
                except Exception:
                    continue

            if price_locator:
                break

    if not price_locator:
        raise Exception("Could not find the Price input field on the Prices panel using accessible roles")

    # 4) Read the current price value
    try:
        current_val = await price_locator.input_value()
    except Exception:
        current_val = (await price_locator.text_content()) or ""

    # 5) Parse numeric value robustly
    s = current_val.replace('\u00a0', '').strip()
    m = re.search(r"([0-9\.,]+)", s)
    if m:
        cleaned = m.group(1)
    else:
        cleaned = re.sub(r"[^0-9\.,]", "", s)

    if "," in cleaned and "." in cleaned:
        cleaned = cleaned.replace(",", "")
    elif "," in cleaned and "." not in cleaned:
        cleaned = cleaned.replace(",", ".")

    if cleaned == "":
        raise Exception(f"Unable to parse current price from '{current_val}'")

    try:
        current_price = float(cleaned)
    except Exception:
        raise Exception(f"Unable to parse current price from '{current_val}' (cleaned: '{cleaned}')")

    # 6) Compute new price reduced by 15%
    new_price = round(current_price * 0.85, 2)
    new_price_str = f"{new_price:.2f}"

    # 7) Fill the price field with the new value and blur so Magento registers change
    await price_locator.fill(new_price_str)
    try:
        await price_locator.press("Tab")
    except Exception:
        pass

    # 8) Click the top-level Save button to persist changes (use root to avoid ambiguity). Do this last.
    await root.get_by_role("button", name="Save").click()
    # allow the save action to initiate
    await asyncio.sleep(1)

